import{_ as e,o as i,c as r,a4 as s}from"./chunks/framework.RZAa07QS.js";const g=JSON.parse('{"title":"Sprint 15 — Testing & Bug Fixes","description":"","frontmatter":{},"headers":[],"relativePath":"plan/sprints/Sprint_15_Testing_Bug_Fixes.md","filePath":"plan/sprints/Sprint_15_Testing_Bug_Fixes.md"}'),n={name:"plan/sprints/Sprint_15_Testing_Bug_Fixes.md"};function o(a,t,d,l,c,p){return i(),r("div",null,[...t[0]||(t[0]=[s('<h1 id="sprint-15-—-testing-bug-fixes" tabindex="-1">Sprint 15 — Testing &amp; Bug Fixes <a class="header-anchor" href="#sprint-15-—-testing-bug-fixes" aria-label="Permalink to &quot;Sprint 15 — Testing &amp; Bug Fixes&quot;">​</a></h1><p><strong>Timeline:</strong> Weeks 29–30 (Dec 2–15, 2026) <strong>Jira:</strong> DA Sprint 15 <strong>Phase:</strong> Phase 7 — Testing, Deployment &amp; Final Report <strong>Goal:</strong> Write unit + integration + E2E tests, fix bugs found during testing, and complete a security audit.</p><hr><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Epic</th><th>Title</th><th>Owner</th></tr></thead><tbody><tr><td>E42</td><td>Unit &amp; Integration Testing</td><td>Trung, Tuấn, Phước, All</td></tr><tr><td>E43</td><td>Bug Fixes &amp; Polish</td><td>All, Lộc, Trung</td></tr></tbody></table><p><strong>Deliverables by end of Sprint 15:</strong></p><ul><li>Unit tests for business-service: AuthService, WorkspaceService, PostService (≥ 70% coverage)</li><li>Unit tests for ai-service: content generation, RAG pipeline, image generation</li><li>Integration tests for main business-service API endpoints</li><li>E2E publishing test on real sandbox accounts (all 5 platforms)</li><li>Security audit checklist completed</li><li>All critical bugs from testing fixed</li></ul><hr><h2 id="epic-e42-—-unit-integration-testing" tabindex="-1">EPIC E42 — Unit &amp; Integration Testing <a class="header-anchor" href="#epic-e42-—-unit-integration-testing" aria-label="Permalink to &quot;EPIC E42 — Unit &amp; Integration Testing&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Task ID</th><th>Description</th><th>Assignee</th><th>Priority</th></tr></thead><tbody><tr><td>DA-E42-01</td><td>Write unit tests for business-service (AuthService, WorkspaceService, PostService)</td><td>Trung (Leader)</td><td>🔴 Critical</td></tr><tr><td>DA-E42-02</td><td>Write unit tests for ai-service (content generation, RAG pipeline, image generation)</td><td>Tuấn (AI)</td><td>🔴 Critical</td></tr><tr><td>DA-E42-03</td><td>Write integration tests for main API endpoints (business-service)</td><td>Phước (Publisher)</td><td>🔴 Critical</td></tr><tr><td>DA-E42-04</td><td>Performance testing (load test with 200 concurrent users)</td><td>All (Team)</td><td>🟡 High</td></tr><tr><td>DA-E42-05</td><td>Test publishing flow E2E on sandbox accounts (FB/IG/TikTok/Threads/Zalo)</td><td>Phước (Publisher)</td><td>🔴 Critical</td></tr></tbody></table><p><strong>Unit test coverage targets:</strong></p><ul><li>business-service: AuthService (login, register, refresh, logout), WorkspaceService (create, invite, remove), PostService (submit, approve, reject, schedule, enqueue)</li><li>Use JUnit 5 + Mockito. Mock MongoDB and Redis.</li></ul><p><strong>ai-service unit tests (DA-E42-02):</strong></p><ul><li>Use <code>pytest</code> + <code>unittest.mock</code></li><li>Content generation: mock Groq API response, verify prompt construction</li><li>RAG pipeline: mock ChromaDB, verify chunk retrieval and context formatting</li><li>Image generation: mock Stability AI, verify S3 upload called with correct params</li></ul><p><strong>Integration tests (DA-E42-03):</strong></p><ul><li>Use <code>@SpringBootTest</code> with <code>Testcontainers</code> (real MongoDB + Redis in Docker)</li><li>Test full auth flow: register → login → refresh → logout</li><li>Test RBAC: verify CONTENT_CREATOR cannot access AGENCY_OWNER endpoints</li><li>Test workspace isolation: verify user A cannot read workspace B data</li></ul><p><strong>Performance testing (DA-E42-04):</strong></p><ul><li>Tool: Apache JMeter or k6</li><li>Scenario: 200 concurrent users, 60-second ramp-up, 5-minute sustained</li><li>Target: p95 &lt; 500ms for non-AI endpoints, no errors &gt; 0.1%</li><li>Test: login, get posts/calendar, submit content request</li></ul><p><strong>E2E publish test (DA-E42-05):</strong></p><ul><li>Use real developer sandbox accounts for each platform</li><li>Test full flow: ContentRequest → AI generate → draft → submit → approve → client approve → publish → verify post appears on platform</li></ul><hr><h2 id="epic-e43-—-bug-fixes-polish" tabindex="-1">EPIC E43 — Bug Fixes &amp; Polish <a class="header-anchor" href="#epic-e43-—-bug-fixes-polish" aria-label="Permalink to &quot;EPIC E43 — Bug Fixes &amp; Polish&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Task ID</th><th>Description</th><th>Assignee</th><th>Priority</th></tr></thead><tbody><tr><td>DA-E43-01</td><td>Sprint retrospective, compile bug list from testing</td><td>All (Team)</td><td>🔴 Critical</td></tr><tr><td>DA-E43-02</td><td>UI responsive fixes (test on various screen sizes: 1920px, 1440px, 1280px, mobile)</td><td>Lộc (Frontend)</td><td>🟡 High</td></tr><tr><td>DA-E43-03</td><td>Security audit checklist (check SQL injection, XSS, CSRF, token handling)</td><td>Trung (Leader)</td><td>🔴 Critical</td></tr></tbody></table><p><strong>Security audit checklist (DA-E43-03):</strong></p><table tabindex="0"><thead><tr><th>Check</th><th>Method</th><th>Owner</th></tr></thead><tbody><tr><td>SQL injection</td><td>Parameterized queries in PostgreSQL (Spring Data JPA)</td><td>Trung</td></tr><tr><td>NoSQL injection</td><td>MongoDB <code>$where</code> disabled, no string concatenation in queries</td><td>Trung</td></tr><tr><td>XSS</td><td>React escapes output by default; verify no <code>dangerouslySetInnerHTML</code></td><td>Lộc</td></tr><tr><td>CSRF</td><td>SameSite cookie + CORS whitelist on gateway</td><td>Trung</td></tr><tr><td>JWT security</td><td>Verify RS256 used, alg=none rejected, blacklist working</td><td>Trung</td></tr><tr><td>AES key exposure</td><td>Verify SOCIAL_TOKEN_ENCRYPTION_KEY not in code or logs</td><td>Trung</td></tr><tr><td>S3 bucket</td><td>Verify bucket is private, all access via presigned URLs</td><td>Trung</td></tr><tr><td>RabbitMQ</td><td>Verify management UI (port 15672) blocked from public</td><td>Trung</td></tr><tr><td>Admin endpoints</td><td>Verify <code>/api/v1/admin/*</code> requires ADMIN role</td><td>Ân</td></tr><tr><td>Internal endpoints</td><td>Verify <code>/internal/*</code> blocked by gateway, X-Internal-Key required</td><td>Tuấn</td></tr></tbody></table><p><strong>Responsive breakpoints (DA-E43-02):</strong></p><ul><li>1920px: full sidebar visible, wide table columns</li><li>1440px: default desktop layout</li><li>1280px: condensed sidebar, compact tables</li><li>Mobile (≤768px): bottom tab navigation, stacked cards</li></ul><hr><h2 id="sprint-15-checklist" tabindex="-1">Sprint 15 Checklist <a class="header-anchor" href="#sprint-15-checklist" aria-label="Permalink to &quot;Sprint 15 Checklist&quot;">​</a></h2><ul><li>[ ] AuthService: register, login, refresh, logout unit tests pass</li><li>[ ] WorkspaceService: create, invite, remove unit tests pass</li><li>[ ] PostService: submit, approve, reject, schedule unit tests pass</li><li>[ ] ai-service: content generation, RAG, image generation unit tests pass</li><li>[ ] Integration tests: auth flow, RBAC, workspace isolation pass</li><li>[ ] JMeter/k6 load test: p95 &lt; 500ms at 200 concurrent users</li><li>[ ] E2E publish test: post published on all 5 platforms</li><li>[ ] Bug list compiled from sprint retrospective</li><li>[ ] All critical bugs fixed</li><li>[ ] Security audit: all 10 checklist items verified</li><li>[ ] UI responsive: no layout breaks at 1920/1440/1280/mobile</li></ul>',30)])])}const h=e(n,[["render",o]]);export{g as __pageData,h as default};
